/**
 * Fake Octocode MCP server for MyGRACE tests (fixtures only — never shipped).
 *
 * Speaks just enough MCP over stdio for `src/grace-code-graph.ts`:
 *   initialize → tools/list → tools/call {graphrag | view_signatures}
 *
 * The wrapper generated by `fake-octocode.ts` appends `--fake-mode <mode>` before
 * the real arguments, so the adapter still sees a normal `mcp --path <root>` argv.
 * Modes:
 *   ok            — recorded fixture payloads
 *   invalid       — non-JSON tool text (INTEGRATION_INVALID_OUTPUT path)
 *   timeout       — delays every tools/call beyond the per-call timeout
 *   tools-missing — tools/list omits the required read-only tools
 */
import { Server } from "@modelcontextprotocol/sdk/server";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { CallToolRequestSchema, ListToolsRequestSchema } from "@modelcontextprotocol/sdk/types.js";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const modeIndex = argv.indexOf("--fake-mode");
const mode = modeIndex >= 0 ? argv[modeIndex + 1] : "ok";

const fixture = (name) => JSON.parse(readFileSync(join(here, name), "utf8"));
const relationships = fixture("graphrag-get-relationships.json");
const signatures = fixture("view-signatures.json");

const TOOLS = [
  { name: "graphrag", description: "fake graph relationships", inputSchema: { type: "object" } },
  { name: "view_signatures", description: "fake file signatures", inputSchema: { type: "object" } },
  { name: "structural_search", description: "fake structural search", inputSchema: { type: "object" } },
];

const text = (value) => ({ content: [{ type: "text", text: value }] });

const server = new Server({ name: "fake-octocode", version: "0.29.2" }, { capabilities: { tools: {} } });

server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: mode === "tools-missing" ? TOOLS.filter((tool) => tool.name === "structural_search") : TOOLS,
}));

server.setRequestHandler(CallToolRequestSchema, async (request) => {
  if (mode === "timeout") await new Promise((resolve) => setTimeout(resolve, 5_000));
  const name = request.params.name;
  if (name === "graphrag") return text(mode === "invalid" ? "not-json{{" : JSON.stringify(relationships));
  if (name === "view_signatures") return text(mode === "invalid" ? "not-json{{" : JSON.stringify(signatures));
  return text("[]");
});

await server.connect(new StdioServerTransport());
